package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var LoanRecData LoanRec
var loanLines []string
var loanIdx int

func pow10Int64(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func parseDisplay(s string, scale int) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, int32(-scale))
}

func parseIntField(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else {
			n = n * 10
		}
	}
	return n
}

func fitPic(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	modulus := decimal.New(1, int32(intDigits+scale))
	scaled := v.Shift(int32(scale)).Truncate(0)
	rem := scaled.Mod(modulus)
	return rem.Shift(int32(-scale))
}

func formatEdited(val decimal.Decimal, picInt string, intDigits int) string {
	absVal := val.Abs()
	scaled := absVal.Shift(2).Truncate(0)
	scaledInt := scaled.IntPart()
	var frac int64
	var intPart int64
	if scaledInt >= 0 {
		frac = scaledInt % 100
		intPart = scaledInt / 100
	} else {
		frac = scaledInt % 100
		intPart = scaledInt / 100
		if frac < 0 {
			frac = -frac
		}
		if intPart < 0 {
			intPart = -intPart
		}
	}
	mod := pow10Int64(intDigits)
	intPartMod := intPart % mod
	intStr := fmt.Sprintf("%0*d", intDigits, intPartMod)

	slotChars := make([]byte, intDigits)
	idx := 0
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == 'Z' || c == '9' {
			slotChars[idx] = c
			idx++
		}
	}
	suppressed := make([]bool, intDigits)
	still := true
	for i := 0; i < intDigits; i++ {
		if still && intStr[i] == '0' && slotChars[i] == 'Z' {
			suppressed[i] = true
		} else {
			suppressed[i] = false
			still = false
		}
	}
	var sb strings.Builder
	digitIdx := 0
	for i := 0; i < len(picInt); i++ {
		c := picInt[i]
		if c == 'Z' || c == '9' {
			if suppressed[digitIdx] {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(intStr[digitIdx])
			}
			digitIdx++
		} else if c == ',' {
			allSup := true
			for k := 0; k < digitIdx; k++ {
				if !suppressed[k] {
					allSup = false
					break
				}
			}
			if allSup {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			sb.WriteByte(c)
		}
	}
	intFormatted := sb.String()
	fracStr := fmt.Sprintf("%02d", frac)
	return intFormatted + "." + fracStr
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			loanLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			loanLines = append(loanLines, sc.Text())
		}
		if err := sc.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		f.Close()
	}
	loanIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if loanIdx >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIdx]
	loanIdx++
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	LoanRecData.LrAcct = line[0:6]
	princStr := line[6:15]
	LoanRecData.LrPrincipal = parseDisplay(princStr, 2)
	rateStr := line[15:19]
	LoanRecData.LrRate = parseDisplay(rateStr, 2)
	yearsStr := line[19:21]
	LoanRecData.LrYears = parseIntField(yearsStr)
}

func ProcessPara() {
	raw := LoanRecData.LrPrincipal.Mul(LoanRecData.LrRate).Mul(decimal.NewFromInt(LoanRecData.LrYears)).Shift(-2)
	rounded := raw.Round(2)
	WsInterest = fitPic(rounded, 9, 2)
	sum := WsTotal.Add(WsInterest)
	WsTotal = fitPic(sum, 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(LoanRecData.LrPrincipal, "Z,ZZZ,ZZ9", 7)
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9", 9)
	os.Stdout.WriteString(LoanRecData.LrAcct + " " + WsPrinEd + " " + WsIntEd + "\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9", 11)
	countStr := fmt.Sprintf("%05d", WsCount)
	os.Stdout.WriteString("RECORDS: " + countStr + "\n")
	os.Stdout.WriteString("TOTAL INTEREST: " + WsTotalEd + "\n")
}

func main() {
	MainPara()
}
